\STATE set $\theta (Y) = Y/\left\| Y \right\|$ and ${\phi _1}({X_1}),...,{\phi _p}({X_p}) = 0$;\\
\STATE Iterate until $e^2(\theta,\phi_1,...,\phi_p)$fails to decrease;\\
